                                Vec::with_capacity((rect.height() * rect.width()) as usize);
                            for row in rect.row_first..=rect.row_last {
                                for col in rect.col_first..=rect.col_last {
                                    cells.push(source_worksheet.cells.get(&(row, col)).cloned());
                                }
                            }
                            cells
