    #[test]
    fn application_evaluate_calculates_expression_against_active_sheet() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:A2".to_string())])
                .expect("Range(A1:A2)"),
        );

        runtime
            .dispatch_set(
                source,
                "Value2",
                OmValue::Array(
                    OmArray::new(2, 1, vec![OmValue::Number(4.0), OmValue::Number(6.0)])
                        .expect("source values"),
                ),
                &[],
            )
            .expect("set evaluate source values");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_invoke(
                        application,
                        "Evaluate",
                        &[OmValue::Text("=SUM(A1:A2)+POWER(2, 3)".to_string())],
                    )
                    .expect("Application.Evaluate"),
            ),
            18.0
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    application,
                    "Evaluate",
                    &[OmValue::Text("SQRT(-1)".to_string())],
                )
                .expect("Application.Evaluate error value"),
            OmValue::Error(CellError::Num)
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Evaluate", &[])
                .expect_err("Application.Evaluate should require one argument")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(application, "Evaluate", &[OmValue::Number(1.0)])
                .expect_err("Application.Evaluate should reject non-text arguments")
                .code,
            OmErrorCode::TypeMismatch
        );
    }

    #[test]
    fn worksheet_evaluate_uses_target_sheet_context() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let first_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let first_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(first_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Sheet1.Range(A1)"),
        );
        runtime
            .dispatch_set(first_a1, "Value2", OmValue::Number(10.0), &[])
            .expect("set Sheet1 A1");

        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(workbook.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );
        let second_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Add", &[])
                .expect("Worksheets.Add"),
        );
        let second_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(second_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Sheet2.Range(A1)"),
        );
        runtime
            .dispatch_set(second_a1, "Value2", OmValue::Number(20.0), &[])
            .expect("set Sheet2 A1");
        runtime
            .dispatch_invoke(first_sheet, "Activate", &[])
            .expect("activate first sheet");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_invoke(
                        application,
                        "Evaluate",
                        &[OmValue::Text("=A1+1".to_string())],
                    )
                    .expect("Application.Evaluate active sheet"),
            ),
            11.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_invoke(
                        second_sheet,
                        "Evaluate",
                        &[OmValue::Text("=A1+1".to_string())],
                    )
                    .expect("Worksheet.Evaluate target sheet"),
            ),
            21.0
        );
        assert_eq!(
            runtime
                .dispatch_invoke(second_sheet, "Evaluate", &[])
                .expect_err("Worksheet.Evaluate should require one argument")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn worksheet_calculate_resolves_sheet_qualified_formula_references() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "Worksheets", &[])
                .expect("Application.Worksheets"),
        );
        let data_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(worksheets, "Add", &[])
                .expect("Worksheets.Add"),
        );
        runtime
            .dispatch_set(
                data_sheet,
                "Name",
                OmValue::Text("Data Sheet".to_string()),
                &[],
            )
            .expect("rename data sheet");
        let sheet1_a1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Sheet1.Range(A1)"),
        );
        let sheet1_b1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Sheet1.Range(B1)"),
        );
        let data_a1_a2 = expect_object_handle(
            runtime
                .dispatch_invoke(data_sheet, "Range", &[OmValue::Text("A1:A2".to_string())])
                .expect("Data Sheet.Range(A1:A2)"),
        );

        runtime
            .dispatch_set(sheet1_a1, "Value2", OmValue::Number(4.0), &[])
            .expect("set Sheet1 A1");
        runtime
            .dispatch_set(
                data_a1_a2,
                "Value2",
                OmValue::Array(
                    OmArray::new(2, 1, vec![OmValue::Number(10.0), OmValue::Number(20.0)])
                        .expect("data values"),
                ),
                &[],
            )
            .expect("set data values");
        runtime
            .dispatch_set(
                sheet1_b1,
                "Formula",
                OmValue::Text("='Data Sheet'!A1+SUM('Data Sheet'!A1:A2)+Sheet1!A1".to_string()),
                &[],
            )
            .expect("set sheet-qualified formula");

        runtime
            .dispatch_invoke(active_sheet, "Calculate", &[])
            .expect("Worksheet.Calculate");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(sheet1_b1, "Value2", &[])
                    .expect("sheet-qualified formula Value2")
            ),
            44.0
        );
    }

    #[test]
    fn application_calculate_updates_lookup_and_reference_formulas() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let vertical_table = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:C4".to_string())])
                .expect("Range(A1:C4)"),
        );
        let horizontal_table = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("E1:H4".to_string())])
                .expect("Range(E1:H4)"),
        );
        let descending_values = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("L1:L4".to_string())])
                .expect("Range(L1:L4)"),
        );
        let formulas = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("J1:J10".to_string())],
                )
                .expect("Range(J1:J10)"),
        );

        runtime
            .dispatch_set(
                vertical_table,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        4,
                        3,
                        vec![
                            OmValue::Text("alpha".to_string()),
                            OmValue::Number(10.0),
                            OmValue::Number(100.0),
                            OmValue::Text("beta".to_string()),
                            OmValue::Number(20.0),
                            OmValue::Number(200.0),
                            OmValue::Text("delta".to_string()),
                            OmValue::Number(40.0),
                            OmValue::Number(400.0),
                            OmValue::Text("gamma".to_string()),
                            OmValue::Number(80.0),
                            OmValue::Number(800.0),
                        ],
                    )
                    .expect("vertical lookup values"),
                ),
                &[],
            )
            .expect("set vertical lookup table");
        runtime
            .dispatch_set(
                horizontal_table,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        4,
                        4,
                        vec![
                            OmValue::Text("Q1".to_string()),
                            OmValue::Text("Q2".to_string()),
                            OmValue::Text("Q3".to_string()),
                            OmValue::Text("Q4".to_string()),
                            OmValue::Number(10.0),
                            OmValue::Number(20.0),
                            OmValue::Number(30.0),
                            OmValue::Number(40.0),
                            OmValue::Number(1.0),
                            OmValue::Number(2.0),
                            OmValue::Number(3.0),
                            OmValue::Number(4.0),
                            OmValue::Number(100.0),
                            OmValue::Number(200.0),
                            OmValue::Number(300.0),
                            OmValue::Number(400.0),
                        ],
                    )
                    .expect("horizontal lookup values"),
                ),
                &[],
            )
            .expect("set horizontal lookup table");
        runtime
            .dispatch_set(
                descending_values,
                "Value2",
                OmValue::Array(
                    OmArray::new(
                        4,
                        1,
                        vec![
                            OmValue::Number(80.0),
                            OmValue::Number(40.0),
                            OmValue::Number(20.0),
                            OmValue::Number(10.0),
                        ],
                    )
                    .expect("descending lookup values"),
                ),
                &[],
            )
            .expect("set descending lookup values");
        runtime
            .dispatch_set(
                formulas,
                "Formula",
                OmValue::Array(
                    OmArray::new(
                        10,
                        1,
                        vec![
                            OmValue::Text("=VLOOKUP(\"beta\", A1:C4, 2, FALSE)".to_string()),
                            OmValue::Text("=VLOOKUP(35, B1:C4, 2)".to_string()),
                            OmValue::Text("=MATCH(\"DELTA\", A1:A4, 0)".to_string()),
                            OmValue::Text("=MATCH(35, B1:B4)".to_string()),
                            OmValue::Text("=INDEX(A1:C4, 3, 3)".to_string()),
                            OmValue::Text("=HLOOKUP(\"Q3\", E1:H4, 2, FALSE)".to_string()),
                            OmValue::Text("=HLOOKUP(2.4, E3:H4, 2)".to_string()),
                            OmValue::Text("=MATCH(35, L1:L4, -1)".to_string()),
                            OmValue::Text("=VLOOKUP(\"missing\", A1:C4, 2, FALSE)".to_string()),
                            OmValue::Text("=INDEX(A1:C4, 5, 1)".to_string()),
                        ],
                    )
                    .expect("lookup formulas"),
                ),
                &[],
            )
            .expect("set lookup formulas");

        runtime
            .dispatch_invoke(runtime.root_application(), "Calculate", &[])
            .expect("Application.Calculate");

        let values = runtime
            .dispatch_get(formulas, "Value2", &[])
            .expect("lookup values after Calculate");
        let OmValue::Array(values) = values else {
            panic!("expected lookup value array");
        };
        assert_eq!(
            values.values,
            vec![
                OmValue::Number(20.0),
                OmValue::Number(200.0),
                OmValue::Number(3.0),
                OmValue::Number(2.0),
                OmValue::Number(400.0),
                OmValue::Number(30.0),
                OmValue::Number(200.0),
                OmValue::Number(2.0),
                OmValue::Error(CellError::NA),
                OmValue::Error(CellError::Ref),
            ]
        );
    }

