    #[test]
    fn range_offset_and_resize_dispatch_transform_rects_and_preserve_projection_views() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B2:C3".to_string())])
                .expect("Range(B2:C3)"),
        );
        let rows = expect_object_handle(
            runtime
                .dispatch_get(range, "Rows", &[])
                .expect("Range.Rows"),
        );
        let unchanged = expect_object_handle(
            runtime
                .dispatch_invoke(range, "Offset", &[])
                .expect("Range.Offset()"),
        );
        let shifted = expect_object_handle(
            runtime
                .dispatch_invoke(
                    range,
                    "Offset",
                    &[OmValue::Number(-1.0), OmValue::Number(-1.0)],
                )
                .expect("Range.Offset(-1, -1)"),
        );
        let column_shifted = expect_object_handle(
            runtime
                .dispatch_invoke(range, "Offset", &[OmValue::Missing, OmValue::Number(1.0)])
                .expect("Range.Offset(, 1)"),
        );
        let rows_shifted = expect_object_handle(
            runtime
                .dispatch_invoke(rows, "Offset", &[OmValue::Number(1.0)])
                .expect("Rows.Offset(1)"),
        );
        let resized = expect_object_handle(
            runtime
                .dispatch_invoke(range, "Resize", &[OmValue::Number(3.0)])
                .expect("Range.Resize(3)"),
        );
        let narrowed = expect_object_handle(
            runtime
                .dispatch_invoke(range, "Resize", &[OmValue::Missing, OmValue::Number(1.0)])
                .expect("Range.Resize(, 1)"),
        );
        let rows_resized = expect_object_handle(
            runtime
                .dispatch_invoke(rows, "Resize", &[OmValue::Number(3.0)])
                .expect("Rows.Resize(3)"),
        );
        let bottom_right = expect_object_handle(
            runtime
                .dispatch_invoke(
                    active_sheet,
                    "Range",
                    &[OmValue::Text("XFD1048576".to_string())],
                )
                .expect("Range(XFD1048576)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(unchanged, "Address", &[])
                    .expect("Range.Offset().Address")
            ),
            "$B$2:$C$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(shifted, "Address", &[])
                    .expect("Range.Offset(-1, -1).Address")
            ),
            "$A$1:$B$2"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(column_shifted, "Address", &[])
                    .expect("Range.Offset(, 1).Address")
            ),
            "$C$2:$D$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(rows_shifted, "Address", &[])
                    .expect("Rows.Offset(1).Address")
            ),
            "$B$3:$C$4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(resized, "Address", &[])
                    .expect("Range.Resize(3).Address")
            ),
            "$B$2:$C$4"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(narrowed, "Address", &[])
                    .expect("Range.Resize(, 1).Address")
            ),
            "$B$2:$B$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(rows_resized, "Address", &[])
                    .expect("Rows.Resize(3).Address")
            ),
            "$B$2:$C$4"
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(rows_shifted, "Count", &[])
                    .expect("Rows.Offset(1).Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(resized, "Count", &[])
                    .expect("Range.Resize(3).Count")
            ),
            6.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(rows_resized, "Count", &[])
                    .expect("Rows.Resize(3).Count")
            ),
            3.0
        );
        assert_eq!(
            runtime
                .dispatch_invoke(range, "Offset", &[OmValue::Number(-2.0)])
                .expect_err("Range.Offset(-2) should be out of bounds")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(bottom_right, "Offset", &[OmValue::Number(1.0)])
                .expect_err("Range.Offset beyond max row should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    bottom_right,
                    "Offset",
                    &[OmValue::Missing, OmValue::Number(1.0)],
                )
                .expect_err("Range.Offset beyond max column should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(range, "Resize", &[OmValue::Number(0.0)])
                .expect_err("Range.Resize(0) should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(bottom_right, "Resize", &[OmValue::Number(2.0)])
                .expect_err("Range.Resize beyond max row should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    bottom_right,
                    "Resize",
                    &[OmValue::Missing, OmValue::Number(2.0)],
                )
                .expect_err("Range.Resize beyond max column should be rejected")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
    fn range_end_dispatch_moves_to_contiguous_region_edge_or_next_content() {
        let mut runtime = ExcelRuntime::new();
        let _workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let b2_b3 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B2:B3".to_string())])
                .expect("Range(B2:B3)"),
        );
        let b5 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B5".to_string())])
                .expect("Range(B5)"),
        );
        runtime
            .dispatch_set(b2_b3, "Value", OmValue::Text("filled".to_string()), &[])
            .expect("B2:B3.Value");
        runtime
            .dispatch_set(b5, "Value", OmValue::Text("next".to_string()), &[])
            .expect("B5.Value");

        let a1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1".to_string())])
                .expect("Range(A1)"),
        );
        let b1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let b4 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B4".to_string())])
                .expect("Range(B4)"),
        );
        let c1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C1".to_string())])
                .expect("Range(C1)"),
        );
        let d1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D1".to_string())])
                .expect("Range(D1)"),
        );

        let end_right = expect_object_handle(
            runtime
                .dispatch_invoke(a1, "End", &[OmValue::Number(f64::from(super::XL_TO_RIGHT))])
                .expect("A1.End(xlToRight)"),
        );
        let end_down = expect_object_handle(
            runtime
                .dispatch_invoke(b1, "End", &[OmValue::Number(f64::from(super::XL_DOWN))])
                .expect("B1.End(xlDown)"),
        );
        let blank_down = expect_object_handle(
            runtime
                .dispatch_invoke(b4, "End", &[OmValue::Number(f64::from(super::XL_DOWN))])
                .expect("B4.End(xlDown)"),
        );
        let blank_up = expect_object_handle(
            runtime
                .dispatch_invoke(b4, "End", &[OmValue::Number(f64::from(super::XL_UP))])
                .expect("B4.End(xlUp)"),
        );
        let end_left = expect_object_handle(
            runtime
                .dispatch_invoke(c1, "End", &[OmValue::Number(f64::from(super::XL_TO_LEFT))])
                .expect("C1.End(xlToLeft)"),
        );
        let blank_left = expect_object_handle(
            runtime
                .dispatch_invoke(d1, "End", &[OmValue::Number(f64::from(super::XL_TO_LEFT))])
                .expect("D1.End(xlToLeft)"),
        );

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(end_right, "Address", &[])
                    .expect("A1.End(xlToRight).Address")
            ),
            "$C$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(end_down, "Address", &[])
                    .expect("B1.End(xlDown).Address")
            ),
            "$B$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(blank_down, "Address", &[])
                    .expect("B4.End(xlDown).Address")
            ),
            "$B$5"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(blank_up, "Address", &[])
                    .expect("B4.End(xlUp).Address")
            ),
            "$B$3"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(end_left, "Address", &[])
                    .expect("C1.End(xlToLeft).Address")
            ),
            "$A$1"
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(blank_left, "Address", &[])
                    .expect("D1.End(xlToLeft).Address")
            ),
            "$C$1"
        );

        assert_eq!(
            runtime
                .dispatch_invoke(a1, "End", &[])
                .expect_err("Range.End should require a direction")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(a1, "End", &[OmValue::Text("down".to_string())])
                .expect_err("Range.End should reject non-numeric direction")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(a1, "End", &[OmValue::Number(-4121.5)])
                .expect_err("Range.End should reject fractional direction")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(a1, "End", &[OmValue::Number(999.0)])
                .expect_err("Range.End should reject unsupported direction")
                .code,
            OmErrorCode::Unsupported
        );
    }

    #[test]
    fn range_delete_dispatch_shifts_cells_up_or_left() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let b1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B1".to_string())])
                .expect("Range(B1)"),
        );
        let c1 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C1".to_string())])
                .expect("Range(C1)"),
        );
        let b2_b4 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B2:B4".to_string())])
                .expect("Range(B2:B4)"),
        );
        runtime
            .dispatch_set(
                b2_b4,
                "Value",
                OmValue::Array(
                    OmArray::new(
                        3,
                        1,
                        vec![
                            OmValue::Number(2.0),
                            OmValue::Number(3.0),
                            OmValue::Number(4.0),
                        ],
                    )
                    .expect("B2:B4 values"),
                ),
                &[],
            )
            .expect("B2:B4.Value");

        assert!(matches!(
            runtime
                .dispatch_invoke(
                    b1,
                    "Delete",
                    &[OmValue::Number(f64::from(super::XL_SHIFT_TO_LEFT))],
                )
                .expect("B1.Delete(xlShiftToLeft)"),
            OmValue::Empty
        ));
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(b1, "Value", &[])
                    .expect("B1 after left shift")
            ),
            "shared"
        );
        assert_eq!(
            runtime
                .dispatch_get(c1, "Value", &[])
                .expect("C1 after left shift"),
            OmValue::Empty
        );

        let b2 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B2".to_string())])
                .expect("Range(B2)"),
        );
        let b3 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B3".to_string())])
                .expect("Range(B3)"),
        );
        let b4 = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("B4".to_string())])
                .expect("Range(B4)"),
        );
        assert!(matches!(
            runtime
                .dispatch_invoke(
                    b2,
                    "Delete",
                    &[OmValue::Number(f64::from(super::XL_SHIFT_UP))],
                )
                .expect("B2.Delete(xlShiftUp)"),
            OmValue::Empty
        ));
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(b2, "Value", &[])
                    .expect("B2 after upward shift")
            ),
            3.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(b3, "Value", &[])
                    .expect("B3 after upward shift")
            ),
            4.0
        );
        assert_eq!(
            runtime
                .dispatch_get(b4, "Value", &[])
                .expect("B4 after upward shift"),
            OmValue::Empty
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Range.Delete")
        ));

        assert_eq!(
            runtime
                .dispatch_invoke(b2, "Delete", &[OmValue::Text("up".to_string())])
                .expect_err("Range.Delete should reject non-numeric Shift")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(b2, "Delete", &[OmValue::Number(-4162.5)])
                .expect_err("Range.Delete should reject fractional Shift")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            runtime
                .dispatch_invoke(b2, "Delete", &[OmValue::Number(999.0)])
                .expect_err("Range.Delete should reject unsupported Shift")
                .code,
            OmErrorCode::Unsupported
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    b2,
                    "Delete",
                    &[
                        OmValue::Number(f64::from(super::XL_SHIFT_UP)),
                        OmValue::Missing,
                    ],
                )
                .expect_err("Range.Delete should reject extra args")
                .code,
            OmErrorCode::InvalidArgument
        );
    }

    #[test]
