    #[test]
    fn range_copy_sets_cut_copy_mode_and_copies_to_destination_range() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let application = runtime.root_application();
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(application, "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("Range(A1:B1)"),
        );
        let destination = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A2".to_string())])
                .expect("Range(A2)"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(source, "Copy", &[])
                .expect("Range.Copy without destination"),
            OmValue::Empty
        ));
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(application, "CutCopyMode", &[])
                    .expect("Application.CutCopyMode after Range.Copy")
            ),
            f64::from(super::XL_COPY)
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(source, "Copy", &[OmValue::Object(destination)])
                .expect("Range.Copy Destination"),
            OmValue::Empty
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(application, "CutCopyMode", &[])
                .expect("Application.CutCopyMode after destination copy")
        ));

        let copied_range = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("A2:B2".to_string())])
                .expect("Range(A2:B2)"),
        );
        let copied_value = expect_object_handle(
            runtime
                .dispatch_invoke(
                    copied_range,
                    "Item",
                    &[OmValue::Number(1.0), OmValue::Number(1.0)],
                )
                .expect("Range(A2:B2).Item(1, 1)"),
        );
        let copied_formula = expect_object_handle(
            runtime
                .dispatch_invoke(
                    copied_range,
                    "Item",
                    &[OmValue::Number(1.0), OmValue::Number(2.0)],
                )
                .expect("Range(A2:B2).Item(1, 2)"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(copied_value, "Value", &[])
                    .expect("A2 Value")
            ),
            42.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(copied_formula, "Formula", &[])
                    .expect("B2 Formula")
            ),
            r#"=UPPER("shared")"#
        );
        assert!(!expect_bool(
            runtime
                .dispatch_get(workbook.0, "Saved", &[])
                .expect("Workbook.Saved after Range.Copy")
        ));
    }

    #[test]
    fn range_copy_destination_supports_cross_workbook_ranges() {
        let mut runtime = ExcelRuntime::new();
        let source_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open source workbook");
        let destination_workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open destination workbook");
        let source_worksheets = expect_object_handle(
            runtime
                .dispatch_get(source_workbook.0, "Worksheets", &[])
                .expect("source Workbook.Worksheets"),
        );
        let source_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(source_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("source Worksheets.Item(1)"),
        );
        let destination_worksheets = expect_object_handle(
            runtime
                .dispatch_get(destination_workbook.0, "Worksheets", &[])
                .expect("destination Workbook.Worksheets"),
        );
        let destination_sheet = expect_object_handle(
            runtime
                .dispatch_invoke(destination_worksheets, "Item", &[OmValue::Number(1.0)])
                .expect("destination Worksheets.Item(1)"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(source_sheet, "Range", &[OmValue::Text("A1:B1".to_string())])
                .expect("source Range(A1:B1)"),
        );
        let destination = expect_object_handle(
            runtime
                .dispatch_invoke(
                    destination_sheet,
                    "Range",
                    &[OmValue::Text("C3".to_string())],
                )
                .expect("destination Range(C3)"),
        );

        assert!(matches!(
            runtime
                .dispatch_invoke(source, "Copy", &[OmValue::Object(destination)])
                .expect("Range.Copy cross-workbook Destination"),
            OmValue::Empty
        ));

        let copied_range = expect_object_handle(
            runtime
                .dispatch_invoke(
                    destination_sheet,
                    "Range",
                    &[OmValue::Text("C3:D3".to_string())],
                )
                .expect("destination Range(C3:D3)"),
        );
        let copied_value = expect_object_handle(
            runtime
                .dispatch_invoke(
                    copied_range,
                    "Item",
                    &[OmValue::Number(1.0), OmValue::Number(1.0)],
                )
                .expect("destination C3"),
        );
        let copied_formula = expect_object_handle(
            runtime
                .dispatch_invoke(
                    copied_range,
                    "Item",
                    &[OmValue::Number(1.0), OmValue::Number(2.0)],
                )
                .expect("destination D3"),
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(copied_value, "Value", &[])
                    .expect("C3 Value")
            ),
            42.0
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(copied_formula, "Formula", &[])
                    .expect("D3 Formula")
            ),
            r#"=UPPER("shared")"#
        );
        assert!(expect_bool(
            runtime
                .dispatch_get(source_workbook.0, "Saved", &[])
                .expect("source Workbook.Saved after Range.Copy")
        ));
        assert!(!expect_bool(
            runtime
                .dispatch_get(destination_workbook.0, "Saved", &[])
                .expect("destination Workbook.Saved after Range.Copy")
        ));
    }

    #[test]
    fn range_copy_destination_rewrites_relative_formula_references() {
        let mut runtime = ExcelRuntime::new();
        runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");
        let active_sheet = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "ActiveSheet", &[])
                .expect("ActiveSheet"),
        );
        let source = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("C1".to_string())])
                .expect("Range(C1)"),
        );
        let destination = expect_object_handle(
            runtime
                .dispatch_invoke(active_sheet, "Range", &[OmValue::Text("D2".to_string())])
                .expect("Range(D2)"),
        );
        runtime
            .dispatch_set(
                source,
                "Formula",
                OmValue::Text(
                    r#"=A1+$B1+C$1+$D$1+SUM(A1:B1)+LOG10(A1)+SUM(A:A)+SUM($B:$C)+SUM(1:1)+SUM($2:$3)&"A:A""#
                        .to_string(),
                ),
                &[],
            )
            .expect("seed C1 Formula");

        runtime
            .dispatch_invoke(source, "Copy", &[OmValue::Object(destination)])
            .expect("Range.Copy Destination with formula");

        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(destination, "Formula", &[])
                    .expect("D2 Formula after Range.Copy")
            ),
            r#"=B2+$B2+D$1+$D$1+SUM(B2:C2)+LOG10(B2)+SUM(B:B)+SUM($B:$C)+SUM(2:2)+SUM($2:$3)&"A:A""#
        );
    }

