    #[test]
    fn workbook_close_dispatch_rejects_invalid_optional_arguments_without_closing() {
        let mut runtime = ExcelRuntime::new();
        let workbook = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open workbook");

        assert_eq!(
            runtime
                .dispatch_invoke(workbook.0, "Close", &[OmValue::Number(1.0)])
                .expect_err("Workbook.Close should reject non-bool SaveChanges")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    workbook.0,
                    "Close",
                    &[OmValue::Bool(true), OmValue::Number(1.0)],
                )
                .expect_err("Workbook.Close should reject non-text Filename")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    workbook.0,
                    "Close",
                    &[
                        OmValue::Bool(false),
                        OmValue::Missing,
                        OmValue::Text("route".to_string()),
                    ],
                )
                .expect_err("Workbook.Close should reject non-bool RouteWorkbook")
                .code,
            OmErrorCode::TypeMismatch
        );
        assert_eq!(
            runtime
                .dispatch_invoke(
                    workbook.0,
                    "Close",
                    &[
                        OmValue::Bool(false),
                        OmValue::Missing,
                        OmValue::Missing,
                        OmValue::Missing,
                    ],
                )
                .expect_err("Workbook.Close should reject extra arguments")
                .code,
            OmErrorCode::InvalidArgument
        );
        assert_eq!(
            expect_text(
                runtime
                    .dispatch_get(workbook.0, "Name", &[])
                    .expect("Workbook should remain open after argument errors")
            ),
            "Workbook"
        );
    }

    #[test]
    fn workbooks_and_worksheets_count_dispatch_report_collection_sizes() {
        let mut runtime = ExcelRuntime::new();
        let first = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open first workbook");
        let second = runtime
            .open_workbook(OpenWorkbookSpec {
                bytes: synthetic_workbook_bytes(),
                format_hint: Some(FileFormat::Xlsx),
                profile: ExcelProfile::Excel365,
                read_only: false,
            })
            .expect("open second workbook");
        let workbooks = expect_object_handle(
            runtime
                .dispatch_get(runtime.root_application(), "Workbooks", &[])
                .expect("Workbooks"),
        );
        let worksheets = expect_object_handle(
            runtime
                .dispatch_get(first.0, "Worksheets", &[])
                .expect("Workbook.Worksheets"),
        );

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(workbooks, "Count", &[])
                    .expect("Workbooks.Count")
            ),
            2.0
        );
        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(worksheets, "Count", &[])
                    .expect("Worksheets.Count")
            ),
            1.0
        );

        runtime
            .close_workbook(second)
            .expect("close second workbook");

        assert_eq!(
            expect_number(
                runtime
                    .dispatch_get(workbooks, "Count", &[])
                    .expect("Workbooks.Count after close")
            ),
            1.0
        );
    }

